// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(0));
        ts = bound(ts, 1, 2**64 - 2);
        vm.warp(ts);
        vm.roll(1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        assertTrue(c.pastBlockTime() == ts + 1, "pastBlockTime must be timestamp+1");
    }
}
